import {validateState,fk,project,viewCamera,jointIds} from './pose-model.js';
// Native raster fallback keeps guides visible in older readers. Source metadata
// keeps joints editable, portable and part of normal board Undo/Redo.
export function poseGuide(state){const s=validateState(state),f=fk(s);return {version:1,kind:'pose',state:s,joints:Object.fromEntries(jointIds.map(id=>{const p=project(f[id].p,viewCamera(s),600,600);return [id,[p.x,p.y]];}))};}
export function validateGuide(stroke){const g=stroke.guide;if(g===undefined)return;if(stroke.brush!=='raster'||!g||g.version!==1||!['image','pose','hair'].includes(g.kind))throw Error('Invalid drawing reference');if(g.kind==='image'){if(Object.keys(g).sort().join(',')!=='kind,version')throw Error('Invalid image reference metadata');return;}
 validateState(g.state);if(g.kind==='pose'){if(!g.joints||Object.keys(g.joints).sort().join(',')!==[...jointIds].sort().join(','))throw Error('Invalid reference joint set');for(const p of Object.values(g.joints))if(!Array.isArray(p)||p.length!==2||p.some(v=>!Number.isFinite(v)||Math.abs(v)>4096))throw Error('Invalid reference joint position');}else if(g.joints!==undefined)throw Error('Hair has no skeleton joints');}
export const guideEdges=state=>Object.values(fk(state)).filter(j=>j.parent).map(j=>[j.parent,j.id]);
export function moveGuideJoint(guide,id,point){const g=structuredClone(guide);if(g.kind!=='pose'||!g.joints[id]||!Array.isArray(point)||point.length!==2||point.some(v=>!Number.isFinite(v)||Math.abs(v)>4096))throw Error('Invalid joint edit');g.joints[id]=[...point];return g;}
export function warpGuide(guide,q,width,height){if(!guide||guide.kind!=='pose')return guide;const g=structuredClone(guide),[[x0,y0],[x1,y1],[x2,y2],[x3,y3]]=q,dx1=x1-x2,dx2=x3-x2,dx3=x0-x1+x2-x3,dy1=y1-y2,dy2=y3-y2,dy3=y0-y1+y2-y3,det=dx1*dy2-dx2*dy1,a=(dx3*dy2-dx2*dy3)/det,b=(dx1*dy3-dx3*dy1)/det;
 for(const [id,[x,y]]of Object.entries(g.joints)){const u=x/width,v=y/height,w=a*u+b*v+1;g.joints[id]=[((x1-x0+a*x1)*u+(x3-x0+b*x3)*v+x0)/w*width,((y1-y0+a*y1)*u+(y3-y0+b*y3)*v+y0)/w*height];}return g;}
export function withoutGuides(board){if(!board.layers.some(l=>l.strokes.some(s=>s.guide)))return board;return {...board,layers:board.layers.map(l=>({...l,strokes:l.strokes.filter(s=>!s.guide)}))};}
// Deterministic frequency palette; fully transparent pixels never become swatches.
export function imageSwatches(data,count=12){if(!(data instanceof Uint8ClampedArray)||data.length%4||!Number.isInteger(count)||count<1||count>32)throw Error('Invalid swatch pixels');const bins=new Map(),stride=Math.max(1,Math.floor(data.length/4/65536));for(let i=0;i<data.length;i+=4*stride){if(data[i+3]<32)continue;const key=(data[i]>>4)*256+(data[i+1]>>4)*16+(data[i+2]>>4),b=bins.get(key)||[0,0,0,0];b[0]++;for(let j=0;j<3;j++)b[j+1]+=data[i+j];bins.set(key,b);}return [...bins.values()].sort((a,b)=>b[0]-a[0]).slice(0,count).map(b=>'#'+b.slice(1).map(v=>Math.round(v/b[0]).toString(16).padStart(2,'0')).join(''));}
// Editor-only viewport; does not mutate the drawing or pose source.
export function fitPoseViewport(points){if(!Array.isArray(points)||!points.length||points.some(p=>!Array.isArray(p)||p.length!==2||p.some(v=>!Number.isFinite(v))))throw Error('Invalid pose view bounds');const xs=points.map(p=>p[0]),ys=points.map(p=>p[1]),x=Math.min(...xs),y=Math.min(...ys),w=Math.max(...xs)-x,h=Math.max(...ys)-y,size=Math.max(60,w,h)*1.12;return{x:x+w/2-size/2,y:y+h/2-size/2,width:size,height:size};}
export function zoomPoseViewport(view,anchor,factor){if(![view.x,view.y,view.width,view.height,anchor.x,anchor.y,factor].every(Number.isFinite)||view.width<=0||view.height<=0||factor<=0)throw Error('Invalid pose view');const f=Math.max(30/view.width,Math.min(1e9/view.width,factor));return{x:anchor.x-(anchor.x-view.x)*f,y:anchor.y-(anchor.y-view.y)*f,width:view.width*f,height:view.height*f};}
// Keep off-frame edits visible in the existing bounded raster, preserving world geometry.
export function poseRasterFrame(guide,transform){validateGuide({brush:'raster',guide});if(guide.kind!=='pose'||!Array.isArray(transform)||transform.length!==6||transform.some(v=>!Number.isFinite(v)))throw Error('Invalid pose frame');const g=structuredClone(guide),points=Object.values(g.joints),head=g.joints.head,neck=g.joints.neck,r=Math.max(12,Math.hypot(head[0]-neck[0],head[1]-neck[1])),xs=points.map(p=>p[0]),ys=points.map(p=>p[1]),left=Math.min(0,Math.floor(Math.min(...xs,head[0]-r)-8)),top=Math.min(0,Math.floor(Math.min(...ys,head[1]-r)-8)),right=Math.max(600,Math.ceil(Math.max(...xs,head[0]+r)+8)),bottom=Math.max(600,Math.ceil(Math.max(...ys,head[1]+r)+8)),scale=Math.max(right-left,bottom-top)/600;
 if(left===0&&top===0&&scale===1)return{guide:g,transform:[...transform]};for(const id of Object.keys(g.joints))g.joints[id]=g.joints[id].map((v,i)=>(v-(i?top:left))/scale);const[a,b,c,d,e,f]=transform;return{guide:g,transform:[a*scale,b*scale,c*scale,d*scale,a*left+c*top+e,b*left+d*top+f]};}
